                        key={ev.id}
                        style={{
                          display: "flex",
                          alignItems: "center",
                          gap: 12,
                          padding: 8,
                          borderBottom: "1px solid #e0e7ff",
                          background: '#fff',
                          marginBottom: 4,
                          borderRadius: 4
                        }}
