                          style={{ width: 100, height: 60, objectFit: "cover", borderRadius: 6 }}
                        />
                        <div>
                          <div style={{ fontWeight: 600 }}>{ev.title}</div>
                          <div style={{ fontSize: 13, color: "#666" }}>
                            Volunteers: {ev.volunteers_count}
                          </div>
                        </div>
                      </div>
                    ))
                  ) : (
                    <p>No top events yet.</p>
                  )}
                </div>
              </div>
            )}
          
            {/* Participants View (Using new 'participants' state) */}
            {activeView === 'participants' && participants && (
              <div style={{ marginTop: 12, background: '#f5f3ff', padding: 12, borderRadius: 8 }}>
                <h4>👥 Participants</h4>
